<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import Icon from './Icon.vue'
import {getVOSBearerToken,clearCachedVOSBearerToken} from './vos-auth'
import logoUrl from '../../assets/icon.svg'
import TaskCard from './TaskCard.vue'
import {createLocaleController,type Locale,type Preference} from './locale'
import {messages} from './messages'
type Task={app_task_id?:string,executor_id?:string,task_id:string,app_id:string,status:string,node_id:string|null,version:number,attempt_count:number,can_retry:boolean,progress:{percent?:number},wait_reasons:string[],created_at:string,result:unknown}
type Node={vos_applications?:{fresh:boolean,data:{app_id:string,installed_app_id:string,state:string}[]},executors?:{id:string}[],managed?:boolean,vos_node?:{display_name?:string,role?:string},vos_metrics?:{fresh:boolean,observed_at:string,data:{cpu_used_percent?:number,memory_used_mib?:number,memory_total_mib?:number}},id:string,capacities:{cpu_millicores:number,memory_mib:number,gpu_slots:number},draining:boolean,heartbeat:string|null,report:{arch?:string,memory_available_mib?:number,memory_total_mib?:number,cpu_used_percent?:number,gpus?:{utilization_percent?:number,total_mib:number,free_mib:number}[]}}
type Reservation={attempt_id:string,task_id:string,node_id:string,state:string,resources:{gpu_slots:number,memory_mib:number}}
const locale=ref<Locale>('en'),preference=ref<Preference>('auto')
const language=createLocaleController({window,document,navigator,storage:localStorage},value=>{locale.value=value})
preference.value=language.preference
const t=(source:string)=>locale.value==='zh-CN'?source:messages[source]?.[locale.value==='en'?0:1]||source
const demo=ref(false)
const appVersion=ref('')
const vosEmbedded=window.parent!==window||location.pathname.startsWith('/app/com.ictrek.v-scheduler')
const page=ref(location.hash==='#api'?'api':'resources'),credential=ref(''),connected=ref(false),busy=ref(false),error=ref(''),tasks=ref<Task[]>([]),nodes=ref<Node[]>([]),reservations=ref<Reservation[]>([]),filter=ref('all'),search=ref(''),selected=ref<Task|null>(null),attempts=ref<any[]>([]),detailTab=ref('overview'),deleting=ref<Task|null>(null),confirmPermit=ref<Reservation|null>(null),stopEvidence=ref(''),copied=ref(false)
const labels=computed<Record<string,string>>(()=>Object.fromEntries(Object.entries({queued:'排队中',assigned:'已预约',running:'运行中',cancelling:'取消中',recovering:'核验中',cancelled:'已取消',succeeded:'已完成',failed:'失败',retry_wait:'等待重试'}).map(([k,v])=>[k,t(v)])))
const shown=computed(()=>tasks.value.filter(task=>(filter.value==='all'||task.status===filter.value)&&(!search.value||(task.task_id+' '+task.app_id).toLowerCase().includes(search.value.toLowerCase()))))
const active=computed(()=>tasks.value.filter(task=>['assigned','running','cancelling','recovering'].includes(task.status)).length)
const queued=computed(()=>tasks.value.filter(task=>['queued','retry_wait'].includes(task.status)).length)
const basePath=new URL('./',location.href.split('#')[0]).pathname
const apiBase=basePath+'api/v1/'
const spec=ref<any>(null),operationKey=ref('GET /discovery'),exampleTab=ref('curl'),discoveryResult=ref<unknown>(null)
const operations=computed(()=>Object.entries(spec.value?.paths||{}).flatMap(([path,methods])=>Object.entries(methods as any).filter(([method])=>['get','post','delete'].includes(method)).map(([method,op])=>({path,method,key:method.toUpperCase()+' '+path,...op as any}))))
const operation=computed(()=>operations.value.find(op=>op.key===operationKey.value)||operations.value[0])
const groupFor=(path:string)=>path==='/discovery'||path==='/openapi.json'?'公开发现':path.startsWith('/tasks')||path==='/events'?'任务接口':path.startsWith('/permits')?'资源许可':path.startsWith('/workers')||path.startsWith('/attempts')?'节点与执行':'管理接口'
const groups=computed(()=>['公开发现','任务接口','资源许可','节点与执行','管理接口'].map(name=>({name,items:operations.value.filter(op=>groupFor(op.path)===name)})).filter(group=>group.items.length))
function resolve(schema:any):any {if(!schema?.$ref)return schema||{};return schema.$ref.split('/').slice(1).reduce((obj:any,key:string)=>obj?.[key],spec.value)||{}}
const requestSchema=computed(()=>resolve(operation.value?.requestBody?.content?.['application/json']?.schema))
const fields=computed(()=>Object.entries(requestSchema.value.properties||{}).map(([name,value])=>({name,...resolve(value),required:requestSchema.value.required?.includes(name)})))
const sample=computed(()=>operation.value?.['x-example']||requestSchema.value.example||{})
const docTitle=computed(()=>operation.value?.['x-title']?.[locale.value]||operation.value?.summary||'')
const docDescription=computed(()=>operation.value?.['x-description']?.[locale.value]||operation.value?.description||'')
const code=computed(()=>exampleTab.value==='json'?JSON.stringify(sample.value,null,2):`curl -X ${operation.value?.method.toUpperCase()||'GET'} '${location.origin}${apiBase}${(operation.value?.path||'/discovery').slice(1)}'${operation.value?.security?.length?" \\\n  -H 'Authorization: Bearer <service-access-token>'":''}${operation.value?.parameters?.some((p:any)=>p.name==='Idempotency-Key')?" \\\n  -H 'Idempotency-Key: stable-business-key'":''}${operation.value?.requestBody?" \\\n  -H 'Content-Type: application/json' \\\n  -d '"+JSON.stringify(sample.value)+"'":''}`)
function prettyTime(value:string){return new Intl.DateTimeFormat(locale.value,{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date(value))}
const errors:Record<string,string>={UNAUTHENTICATED:'未授权或令牌无效',FORBIDDEN:'权限不足',STATE_CONFLICT:'任务或资源状态不允许此操作',RETRY_NOT_ALLOWED:'任务或资源状态不允许此操作',TASK_NOT_STOPPED:'任务或资源状态不允许此操作',TEMPORARILY_UNAVAILABLE:'调度器暂不可用',WAIT_RESOURCE:'资源忙，请稍后重试',WAIT_RESOURCE_OR_NODE:'资源忙，请稍后重试'}
async function api(path:string,body?:unknown,method?:string,extra:Record<string,string>={},retried=false){
 const response=await fetch(apiBase+path,{method:method||(body===undefined?'GET':'POST'),headers:{Authorization:`Bearer ${credential.value}`,'Content-Type':'application/json',...extra},body:body===undefined?undefined:JSON.stringify(body)})
 if(response.status===401&&vosEmbedded&&!retried){clearCachedVOSBearerToken();credential.value=await getVOSBearerToken()||'';if(credential.value)return api(path,body,method,extra,true)}
 const text=await response.text();let payload:any;try{payload=JSON.parse(text)}catch{throw Error(`HTTP ${response.status}`)}
 if(!response.ok)throw Error(payload.code||`HTTP ${response.status}`)
 return payload.data
}
function showError(e:unknown){error.value=(e instanceof Error?e.message:String(e)).replace(/^Error: /,'')}
async function refresh(){if(!connected.value||busy.value)return;busy.value=true;try{const [taskData,nodeData,reserved]=await Promise.all([api('tasks?limit=200'),api('nodes'),api('reservations')]);tasks.value=taskData.items;nodes.value=nodeData;reservations.value=reserved;error.value='';if(selected.value){selected.value=tasks.value.find(task=>task.task_id===selected.value?.task_id)||null}}catch(e){showError(e)}finally{busy.value=false}}
async function connect(){
 demo.value=false;error.value='';busy.value=true
 try{
  credential.value=await getVOSBearerToken()||''
  if(!credential.value){error.value='VOS_LOGIN_REQUIRED';return}
  const state=await (await fetch(apiBase+'setup')).json();appVersion.value=state.data?.version||''
  if(state.data?.ready===false){await api('setup',{});await new Promise(resolve=>setTimeout(resolve,1000))}
  tasks.value=[];nodes.value=[];reservations.value=[];connected.value=true
 }catch(e){showError(e)}finally{busy.value=false}
 await refresh();if(error.value)connected.value=false
}
function logout(){demo.value=false;connected.value=false;credential.value='';tasks.value=[];nodes.value=[];reservations.value=[];selected.value=null}
async function cancel(task:Task){if(demo.value){task.status='cancelled';task.can_retry=false;reservations.value=reservations.value.filter(r=>r.task_id!==task.task_id);return}try{await api(`tasks/${task.task_id}/cancel`,{});await refresh()}catch(e){showError(e)}}
async function retry(task:Task){if(demo.value){task.status='queued';task.can_retry=false;task.node_id=null;task.progress={};return}try{await api(`tasks/${task.task_id}/retry`,{},'POST',{'Idempotency-Key':(crypto.randomUUID?.()||Array.from(crypto.getRandomValues(new Uint8Array(16))).map(b=>b.toString(16).padStart(2,'0')).join(''))});await refresh();if(selected.value?.task_id===task.task_id)await select(task)}catch(e){showError(e)}}
async function remove(){if(!deleting.value)return;if(demo.value){tasks.value=tasks.value.filter(t=>t.task_id!==deleting.value?.task_id);selected.value=null;deleting.value=null;return}try{await api(`tasks/${deleting.value.task_id}`,undefined,'DELETE');deleting.value=null;await refresh()}catch(e){showError(e)}}
async function drain(node:Node){if(demo.value){node.draining=!node.draining;return}try{await api(`nodes/${node.id}/drain`,{draining:!node.draining});await refresh()}catch(e){showError(e)}}
async function confirmStop(){if(!confirmPermit.value||!stopEvidence.value.trim())return;try{await api(`permits/${confirmPermit.value.attempt_id}/confirm-stopped`,{stopped:true,evidence:stopEvidence.value});confirmPermit.value=null;stopEvidence.value='';await refresh()}catch(e){showError(e)}}
async function select(task:Task){selected.value=task;detailTab.value='overview';if(demo.value){attempts.value=[];return}try{attempts.value=await api(`tasks/${task.task_id}/attempts`)}catch(e){showError(e)}}
function targetNode(task:Task){return task.node_id||nodes.value.find(n=>n.executors?.some(e=>e.id===task.executor_id))?.id||'unassigned'}
function recentTasks(id:string){return shown.value.filter(task=>targetNode(task)===id&&['failed','succeeded','cancelled'].includes(task.status)).sort((a,b)=>b.created_at.localeCompare(a.created_at)).slice(0,2)}
function laneTasks(id:string,waiting:boolean){return shown.value.filter(task=>targetNode(task)===id&&(waiting?['queued','retry_wait'].includes(task.status):['assigned','running','cancelling','recovering'].includes(task.status))).sort((a,b)=>a.created_at.localeCompare(b.created_at)||a.task_id.localeCompare(b.task_id))}
const lanes=computed(()=>nodes.value.filter(n=>n.managed!==false).map(n=>({id:n.id,name:n.vos_node?.display_name||n.id,draining:n.draining})).concat(tasks.value.some(t=>targetNode(t)==='unassigned')?[{id:'unassigned',name:t('待分配'),draining:false}]:[]))
function preview(){demo.value=true;connected.value=false;error.value='';selected.value=null;filter.value='all';search.value='';const now=Date.now();nodes.value=[{id:'demo-gpu-01',managed:true,capacities:{cpu_millicores:8000,memory_mib:32768,gpu_slots:1},draining:false,heartbeat:new Date(now).toISOString(),report:{cpu_used_percent:38,memory_total_mib:32768,memory_available_mib:18432,gpus:[{total_mib:24576,free_mib:12288,utilization_percent:72}]},executors:[{id:'demo.image'}]},{id:'demo-gpu-02',managed:true,capacities:{cpu_millicores:4000,memory_mib:16384,gpu_slots:1},draining:false,heartbeat:new Date(now).toISOString(),report:{cpu_used_percent:12,memory_total_mib:16384,memory_available_mib:14336},executors:[{id:'demo.batch'}]}];tasks.value=[['000001','running','demo-gpu-01','image-studio','demo.image',0.58],['000002','queued',null,'image-studio','demo.image',0],['000003','queued',null,'image-studio','demo.image',0],['000004','queued',null,'demo-app','demo.batch',0],['000005','failed','demo-gpu-02','demo-app','demo.batch',0],['000006','succeeded','demo-gpu-01','image-studio','demo.image',1]].map(([id,status,node,app,executor,progress],index)=>({task_id:'demo-'+id,app_task_id:'sample-'+id,executor_id:executor as string,app_id:app as string,status:status as string,node_id:node as string|null,version:1,attempt_count:status==='queued'?0:1,can_retry:status==='failed',progress:{percent:progress as number},wait_reasons:[],created_at:new Date(now+index*1000).toISOString(),result:{}}));reservations.value=[{attempt_id:'demo-attempt',task_id:'demo-000001',node_id:'demo-gpu-01',state:'active',resources:{gpu_slots:1,memory_mib:8192}}]}
function cpuUsage(node:Node){const fresh=demo.value||node.heartbeat&&Date.now()-Date.parse(node.heartbeat)<12000;return fresh?node.report.cpu_used_percent:node.vos_metrics?.fresh?node.vos_metrics.data.cpu_used_percent:undefined}
function used(node:Node){return reservations.value.filter(r=>r.node_id===node.id).reduce((n,r)=>n+r.resources.gpu_slots,0)}
async function copy(value:string){try{await navigator.clipboard.writeText(value);copied.value=true;setTimeout(()=>copied.value=false,1500)}catch{error.value='COPY_UNAVAILABLE'}}
async function tryDiscovery(){try{discoveryResult.value=await (await fetch(apiBase+'discovery')).json()}catch(e){showError(e)}}
watch(page,value=>{location.hash=value==='api'?'api':'resources';selected.value=null})
watch(locale,()=>{document.title=`V-Scheduler · ${t('资源调度')}`})
let timer:ReturnType<typeof setInterval>
onMounted(async()=>{await connect();timer=setInterval(refresh,2500);try{spec.value=await (await fetch(apiBase+'openapi.json')).json()}catch{if(!error.value)error.value='加载接口文档失败'}})
onUnmounted(()=>{clearInterval(timer);language.dispose()})
</script>
<template>
 <div class="shell">
  <aside><div class="brand"><img :src="logoUrl" alt=""><div>V-Scheduler<small>{{t('资源调度')}}</small></div></div><nav><button :class="{current:page==='resources'}" @click="page='resources'"><Icon name="queue"/>{{t('资源与任务')}}</button><button :class="{current:page==='api'}" @click="page='api'"><Icon name="book"/>{{t('API 文档')}}</button></nav><div class="aside-note"><span class="connection-dot" :class="{on:connected}"></span>{{t(demo?'演示模式':connected?'已连接':'未连接')}}<small>{{t('按能力分配')}}<br>{{t('确认停止后释放')}}</small><small v-if="appVersion">v{{appVersion}}</small></div></aside>
  <main>
   <header><div><h1>{{t(page==='api'?'API 文档':'资源与任务')}}</h1><p>{{t(page==='api'?'接口标准、认证方式与可复制的请求示例。':'查看执行资源、预约与排队任务。')}}</p></div><div class="header-actions"><label class="locale-control"><Icon name="globe"/><select v-model="preference" :aria-label="t('界面语言')" @change="language.setPreference(preference)"><option value="auto">{{t('跟随 VOS')}}</option><option value="zh-CN">简体中文</option><option value="en">English</option><option value="zh-TW">繁體中文</option></select></label></div></header>
   <div v-if="error" class="error" role="alert">{{t(errors[error]||error)}}<code v-if="errors[error]">{{error}}</code></div>
   <template v-if="page==='resources'">
    <section v-if="!connected&&!demo&&error" class="login"><div class="login-mark"><Icon name="shield"/></div><h2>{{t('连接 VOS')}}</h2><p>{{t('使用当前 VOS 管理员身份连接，首次使用自动准备 PGV 数据库。')}}</p><button :disabled="busy" @click="connect">{{t('重试连接')}}</button></section>

    <div v-if="demo" class="demo-banner"><div><strong>{{t('演示模式')}}</strong><span>{{t('样例数据；操作只影响当前演示，不会执行计算或修改真实任务。')}}</span></div><button class="quiet" @click="logout">{{t('连接真实调度器')}}</button></div>
    <template v-if="connected||demo">
     <section class="summary"><div v-for="metric in [{name:'排队任务',n:queued,icon:'queue'},{name:'执行与核验',n:active,icon:'play'},{name:'纳管节点',n:nodes.filter(n=>n.managed!==false).length,icon:'server'},{name:'未释放预约',n:reservations.length,icon:'clock'}]"><span>{{t(metric.name)}}</span><div><strong>{{metric.n}}</strong><Icon :name="metric.icon"/></div><i></i></div></section>
     <section class="section panel schedule-panel"><div class="section-head"><div><h2>{{t('任务排布')}}</h2><p>{{t('按目标节点查看执行与等待顺序；确认停止后才释放资源。')}}</p></div><span>{{t('队列顺序：先提交先执行')}}</span></div><div class="schedule-lanes"><article v-for="lane in lanes" :key="lane.id" class="schedule-lane"><header><Icon name="server"/><strong>{{lane.name}}</strong><span>{{laneTasks(lane.id,true).length}} {{t('等待')}}</span><span v-if="lane.draining" class="status">{{t('排空中')}}</span></header><div class="lane-current"><label>{{t('正在执行')}}</label><TaskCard v-for="task in laneTasks(lane.id,false)" :key="task.task_id" :task="task" :labels="labels" :t="t" @detail="select(task)" @cancel="cancel(task)" @retry="retry(task)" @delete="deleting=task"/><p v-if="!laneTasks(lane.id,false).length" class="lane-empty">{{t('当前空闲')}}</p></div><div class="lane-queue"><label>{{t('等待队列')}}</label><TaskCard v-for="(task,index) in laneTasks(lane.id,true)" :key="task.task_id" :task="task" :position="index+1" :labels="labels" :t="t" @detail="select(task)" @cancel="cancel(task)" @retry="retry(task)" @delete="deleting=task"/><p v-if="!laneTasks(lane.id,true).length" class="lane-empty">{{t('没有等待任务')}}</p></div><div v-if="recentTasks(lane.id).length" class="lane-recent"><label>{{t('最近结束')}}</label><TaskCard v-for="task in recentTasks(lane.id)" :key="task.task_id" :task="task" :labels="labels" :t="t" @detail="select(task)" @retry="retry(task)" @delete="deleting=task"/></div></article></div><p v-if="!lanes.length" class="empty">{{t('尚无已配置节点。')}}</p></section>
     <section class="section panel"><div class="section-head"><h2>{{t('执行资源')}}</h2><span>{{t('每 2.5 秒刷新')}}</span></div><div class="node-list"><article v-for="node in nodes" :key="node.id"><div><label>{{t('名称')}}</label><h3><Icon name="server"/>{{node.vos_node?.display_name||node.id}}</h3><small v-if="node.vos_node">{{node.vos_node.role}} · {{node.id}}</small></div><div><label>{{t('状态')}}</label><span class="node-state"><i :class="{online:node.heartbeat&&Date.now()-Date.parse(node.heartbeat)<12000}"></i>{{t(node.managed===false?'仅观察':node.draining?'排空中':demo||node.heartbeat&&Date.now()-Date.parse(node.heartbeat)<12000?'在线':'离线')}}</span></div><div><label>{{t('CPU 预算')}}</label><strong>{{node.capacities.cpu_millicores/1000}} vCPU</strong></div><div><label>{{t('内存预算')}}</label><strong>{{Math.round(node.capacities.memory_mib/1024)}} GiB</strong></div><div class="node-meter"><label>{{t('GPU 槽位')}}</label><strong>{{used(node)}} / {{node.capacities.gpu_slots}}</strong><div class="meter"><div :style="{width:`${node.capacities.gpu_slots?Math.min(100,used(node)/node.capacities.gpu_slots*100):0}%`}"></div></div></div><button v-if="node.managed!==false" class="quiet" @click="drain(node)">{{t(node.draining?'恢复接收':'排空节点')}}</button><div class="node-telemetry"><label>{{t('实际使用')}}</label><span>CPU {{cpuUsage(node)?.toFixed(1)??'—'}}%</span><span v-if="(demo||node.heartbeat&&Date.now()-Date.parse(node.heartbeat)<12000)&&node.report.memory_total_mib">RAM {{((node.report.memory_total_mib-(node.report.memory_available_mib||0))/1024).toFixed(1)}} / {{(node.report.memory_total_mib/1024).toFixed(1)}} GiB</span><span v-else-if="node.vos_metrics?.fresh">RAM {{((node.vos_metrics.data.memory_used_mib||0)/1024).toFixed(1)}} / {{((node.vos_metrics.data.memory_total_mib||0)/1024).toFixed(1)}} GiB</span><template v-if="demo||node.heartbeat&&Date.now()-Date.parse(node.heartbeat)<12000"><span v-for="gpu in node.report.gpus">GPU {{gpu.utilization_percent??'—'}}% · VRAM {{((gpu.total_mib-gpu.free_mib)/1024).toFixed(1)}} / {{(gpu.total_mib/1024).toFixed(1)}} GiB</span></template><span v-if="node.vos_applications?.fresh">{{t('本机已安装应用')}}: {{node.vos_applications.data.map(a=>a.app_id).join(', ')||'—'}}</span><span v-if="node.executors?.length">{{t('已绑定执行器')}}: {{node.executors.map(e=>e.id).join(', ')}}</span><small v-if="node.vos_metrics&&!node.vos_metrics.fresh">{{t('VOS 数据已过期')}}</small></div></article><p v-if="!nodes.length" class="empty">{{t('尚无已配置节点。')}}</p></div></section>
     <section class="section panel"><div class="section-head"><h2>{{t('任务队列')}}</h2></div><div class="table-toolbar"><select v-model="filter" :aria-label="t('筛选任务状态')"><option value="all">{{t('全部状态')}}</option><option v-for="(name,value) in labels" :value="value">{{name}}</option></select><label class="search"><Icon name="search"/><input v-model="search" :placeholder="t('搜索任务 ID 或应用')" :aria-label="t('搜索任务 ID 或应用')"></label><button class="quiet refresh" :disabled="busy" @click="refresh"><Icon name="refresh"/>{{t('刷新')}}</button></div><div class="table-wrap"><table><thead><tr><th>{{t('任务 / 应用')}}</th><th>{{t('状态')}}</th><th>{{t('执行节点')}}</th><th>{{t('进度')}}</th><th>{{t('创建时间')}}</th><th>{{t('操作')}}</th></tr></thead><tbody><tr v-for="task in shown" :key="task.task_id" :class="{selected:selected?.task_id===task.task_id}"><td><button class="task-link" @click="select(task)">{{task.app_task_id||task.task_id.slice(0,8)}}</button><small>{{task.app_id}}</small></td><td><span class="status" :class="task.status"><i></i>{{labels[task.status]||task.status}}</span><small v-if="task.status==='queued'">{{t('等待资源或节点')}}</small></td><td>{{targetNode(task)==='unassigned'?t('待分配'):targetNode(task)}}</td><td><span>{{Math.round((task.progress?.percent||0)*100)}}%</span><div class="meter mini"><div :style="{width:`${(task.progress?.percent||0)*100}%`}"></div></div></td><td class="date">{{prettyTime(task.created_at)}}</td><td class="actions"><button v-if="['queued','retry_wait','assigned','running','recovering'].includes(task.status)" class="text-button" @click="cancel(task)">{{t('取消')}}</button><button v-if="task.can_retry" class="text-button" @click="retry(task)">{{t('重试')}}</button><button v-if="['failed','succeeded','cancelled'].includes(task.status)" class="text-button subdued" @click="deleting=task">{{t('删除')}}</button><button class="icon-button" :aria-label="t('任务详情')" @click="select(task)"><Icon name="arrow"/></button></td></tr></tbody></table><p v-if="!shown.length" class="empty">{{t('此状态下没有任务。')}}</p></div><div class="table-footer">{{t('当前筛选任务数')}}: {{shown.length}}</div></section>
     <section class="section panel"><div class="section-head"><h2>{{t('预约台账')}}</h2></div><div class="reservation-list"><div v-for="reserved in reservations" :key="reserved.attempt_id"><Icon name="clock"/><div><strong>{{reserved.task_id.startsWith('permit:')?t('在线许可'):reserved.task_id.slice(0,8)}}</strong><small>{{reserved.node_id}} · {{reserved.resources.memory_mib}} MiB · {{reserved.resources.gpu_slots}} GPU</small></div><span class="status" :class="reserved.state==='suspect'?'recovering':'assigned'">{{reserved.state}}</span><button v-if="reserved.state==='suspect'&&reserved.task_id.startsWith('permit:')" class="quiet" @click="confirmPermit=reserved">{{t('确认该执行已停止')}}</button></div><p v-if="!reservations.length" class="empty">{{t('尚无资源预约。')}}</p></div></section>
    </template>
   </template>
   <template v-else>
    <section class="api-intro"><div><Icon name="code"/><h2>V-Scheduler API <span>v1</span></h2><p>{{t('仅展示当前已实现接口；完整设计中的后续能力不在此处宣称可用。')}}</p></div><a class="quiet button" :href="apiBase+'openapi.json'" target="_blank">{{t('获取 OpenAPI')}}</a></section>
    <div class="api-layout"><div class="api-index"><section v-for="group in groups" :key="group.name"><h3>{{t(group.name)}}</h3><button v-for="op in group.items" :class="{active:operationKey===op.key}" @click="operationKey=op.key;discoveryResult=null"><span class="method" :class="op.method">{{op.method.toUpperCase()}}</span><code>{{op.path}}</code></button></section></div><div class="api-content" v-if="operation"><div class="endpoint-title"><span class="method" :class="operation.method">{{operation.method.toUpperCase()}}</span><code>{{operation.path}}</code></div><h2>{{docTitle}}</h2><p>{{docDescription}}</p><section class="doc-section"><h3>{{t('认证')}}</h3><p>{{t(operation.security?.length?'使用服务身份的 Bearer token。工作节点使用独立身份，管理员令牌只用于管理操作。':'此接口公开，无需访问令牌。')}}</p><div class="auth-line"><Icon name="shield"/><code>{{operation['x-required-scope']||'public'}}</code></div></section><section v-if="fields.length" class="doc-section"><h3>{{t('请求参数')}}</h3><table class="fields"><thead><tr><th>{{t('字段')}}</th><th>{{t('类型')}}</th><th></th></tr></thead><tbody><tr v-for="field in fields"><td><code>{{field.name}}</code></td><td>{{field.type||'object'}}</td><td><span :class="{required:field.required}">{{t(field.required?'必填':'可选')}}</span></td></tr></tbody></table></section><section class="doc-section"><div class="section-head"><h3>{{t('请求示例')}}</h3><button class="quiet small" @click="copy(code)"><Icon name="copy"/>{{t(copied?'已复制':'复制')}}</button></div><div class="code-tabs"><button :class="{active:exampleTab==='curl'}" @click="exampleTab='curl'">cURL</button><button :class="{active:exampleTab==='json'}" @click="exampleTab='json'">JSON</button></div><pre class="code-block">{{code}}</pre><p class="doc-note">{{t('每个提交使用稳定的 Idempotency-Key；超时后保留原键重试。')}}</p></section><section class="doc-section"><h3>{{t('响应')}}</h3><p>{{t('成功受理不代表计算完成。取消受理后，须等待停止确认。')}}</p><div class="response-codes"><code v-for="(value,status) in operation.responses" :key="status">{{status}}</code></div><button v-if="operation.path==='/discovery'" class="quiet" @click="tryDiscovery"><Icon name="play"/>{{t('试调用发现接口')}}</button><pre v-if="discoveryResult" class="code-block">{{JSON.stringify(discoveryResult,null,2)}}</pre></section></div></div>
   </template>
  </main>
  <div v-if="selected" class="drawer-backdrop" @click.self="selected=null"><section class="drawer"><div class="drawer-title"><h2>{{selected.task_id.slice(0,8)}}</h2><span class="status" :class="selected.status">{{labels[selected.status]}}</span><button class="icon-button" :aria-label="t('关闭')" @click="selected=null"><Icon name="close"/></button></div><p>{{selected.app_id}}</p><div class="detail-tabs"><button v-for="tab in [{key:'overview',label:'概览'},{key:'attempts',label:'执行历史'},{key:'json',label:'请求与结果'}]" :class="{active:detailTab===tab.key}" @click="detailTab=tab.key">{{t(tab.label)}}</button></div><dl v-if="detailTab==='overview'"><dt>{{t('任务 ID')}}</dt><dd class="mono">{{selected.task_id}}</dd><dt>{{t('应用')}}</dt><dd>{{selected.app_id}}</dd><dt>{{t('状态')}}</dt><dd>{{labels[selected.status]}}</dd><dt>{{t('执行节点')}}</dt><dd>{{selected.node_id}}</dd><dt>{{t('进度')}}</dt><dd>{{Math.round((selected.progress?.percent||0)*100)}}%</dd><dt>{{t('创建时间')}}</dt><dd>{{prettyTime(selected.created_at)}}</dd><dt>{{t('执行代次')}}</dt><dd>{{selected.attempt_count}}</dd><dt>Fence</dt><dd>{{(selected as any).fence}}</dd></dl><div v-else-if="detailTab==='attempts'" class="attempt-list"><article v-for="attempt in attempts" :key="attempt.attempt_id"><span class="status" :class="attempt.status">{{labels[attempt.status]||attempt.status}}</span><h3>{{t('执行代次')}} {{attempt.fence}}</h3><p class="mono">{{attempt.attempt_id}}</p><small>{{attempt.stopped_at?t('已确认停止'):t('核验中')}}</small><pre>{{JSON.stringify(attempt.result,null,2)}}</pre></article><p v-if="!attempts.length" class="empty">{{t('没有执行记录。')}}</p></div><pre v-else class="code-block">{{JSON.stringify(selected,null,2)}}</pre><div class="drawer-actions"><button v-if="selected.can_retry" @click="retry(selected)">{{t('重试')}}</button><button v-if="['succeeded','failed','cancelled'].includes(selected.status)" class="quiet" @click="deleting=selected">{{t('删除')}}</button></div></section></div>
  <div v-if="deleting||confirmPermit" class="modal-backdrop" @click.self="deleting=null;confirmPermit=null"><section class="modal" role="dialog" aria-modal="true"><Icon :name="deleting?'trash':'shield'"/><h2>{{t(deleting?'删除任务记录？':'确认该执行已停止')}}</h2><p>{{t(deleting?'任务将从列表移除。输出文件不会被删除，审计记录会保留。':'仅在核验执行端确实停止后提交。')}}</p><code>{{deleting?.task_id||confirmPermit?.attempt_id}}</code><label v-if="confirmPermit">{{t('停止证据')}}<textarea v-model="stopEvidence" rows="3"></textarea></label><div><button class="quiet" @click="deleting=null;confirmPermit=null">{{t(deleting?'保留任务':'取消')}}</button><button :disabled="!!confirmPermit&&!stopEvidence.trim()" @click="deleting?remove():confirmStop()">{{t(deleting?'确认删除':'提交停止确认')}}</button></div></section></div>
 </div>
</template>
